<?php
function ensure_cms_schema(): void {
    static $done=false; if($done || !is_installed()) return; $done=true;
    try {
        $pdo=db();
        $pdo->exec("CREATE TABLE IF NOT EXISTS cms_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,parent_id BIGINT UNSIGNED NULL,description TEXT NULL,archive_color VARCHAR(7) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(parent_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $sql=[
"CREATE TABLE IF NOT EXISTS cms_posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, post_type ENUM('post','page') NOT NULL DEFAULT 'post', title VARCHAR(220) NOT NULL DEFAULT '', slug VARCHAR(220) NOT NULL, content LONGTEXT NOT NULL, excerpt TEXT NULL, status ENUM('draft','published','trash','private','pending') NOT NULL DEFAULT 'draft', visibility ENUM('public','private','password') NOT NULL DEFAULT 'public', password_hash VARCHAR(255) NULL, author_id BIGINT UNSIGNED NULL, parent_id BIGINT UNSIGNED NULL, template VARCHAR(120) NULL, menu_order INT NOT NULL DEFAULT 0, featured_image_url TEXT NULL, transparent_header TINYINT(1) NOT NULL DEFAULT 0, display_title TINYINT(1) NOT NULL DEFAULT 1, layout VARCHAR(40) NOT NULL DEFAULT 'default', content_style VARCHAR(40) NOT NULL DEFAULT 'default', vertical_padding VARCHAR(40) NOT NULL DEFAULT 'default', comments_enabled TINYINT(1) NOT NULL DEFAULT 1, pings_enabled TINYINT(1) NOT NULL DEFAULT 1, scheduled_at DATETIME NULL, published_at DATETIME NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, deleted_at DATETIME NULL, UNIQUE KEY uq_cms_post_slug_type(post_type,slug), INDEX(post_type), INDEX(status), INDEX(author_id), INDEX(parent_id), INDEX(updated_at), CONSTRAINT fk_cms_post_author FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT fk_cms_post_parent FOREIGN KEY(parent_id) REFERENCES cms_posts(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS cms_tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, description TEXT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS cms_post_tags (post_id BIGINT UNSIGNED NOT NULL, tag_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(post_id,tag_id), CONSTRAINT fk_cms_pt_post FOREIGN KEY(post_id) REFERENCES cms_posts(id) ON DELETE CASCADE, CONSTRAINT fk_cms_pt_tag FOREIGN KEY(tag_id) REFERENCES cms_tags(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS cms_post_categories (post_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(post_id,category_id), CONSTRAINT fk_cms_pc_post FOREIGN KEY(post_id) REFERENCES cms_posts(id) ON DELETE CASCADE, CONSTRAINT fk_cms_pc_cat FOREIGN KEY(category_id) REFERENCES cms_categories(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS cms_revisions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, post_id BIGINT UNSIGNED NOT NULL, revision_no INT UNSIGNED NOT NULL, title VARCHAR(220) NOT NULL, slug VARCHAR(220) NOT NULL, content LONGTEXT NOT NULL, meta_json LONGTEXT NOT NULL, author_id BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL, UNIQUE KEY uq_cms_revision(post_id,revision_no), INDEX(post_id), CONSTRAINT fk_cms_revision_post FOREIGN KEY(post_id) REFERENCES cms_posts(id) ON DELETE CASCADE, CONSTRAINT fk_cms_revision_author FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS cms_comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, post_id BIGINT UNSIGNED NOT NULL, parent_id BIGINT UNSIGNED NULL, author_name VARCHAR(180) NOT NULL, author_email VARCHAR(190) NULL, author_url VARCHAR(500) NULL, content TEXT NOT NULL, status ENUM('pending','approved','spam','trash') NOT NULL DEFAULT 'pending', ip_hash CHAR(64) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX(post_id), INDEX(status), INDEX(created_at), CONSTRAINT fk_cms_comment_post FOREIGN KEY(post_id) REFERENCES cms_posts(id) ON DELETE CASCADE, CONSTRAINT fk_cms_comment_parent FOREIGN KEY(parent_id) REFERENCES cms_comments(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS cms_post_meta (post_id BIGINT UNSIGNED NOT NULL, meta_key VARCHAR(120) NOT NULL, meta_value LONGTEXT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(post_id,meta_key), CONSTRAINT fk_cms_meta_post FOREIGN KEY(post_id) REFERENCES cms_posts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
"CREATE TABLE IF NOT EXISTS cms_user_preferences (user_id BIGINT UNSIGNED NOT NULL, pref_key VARCHAR(120) NOT NULL, pref_value LONGTEXT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(user_id,pref_key), INDEX(pref_key), CONSTRAINT fk_cms_pref_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        ];
        foreach($sql as $q) $pdo->exec($q);
        try{$pdo->exec("CREATE TABLE IF NOT EXISTS cms_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,parent_id BIGINT UNSIGNED NULL,description TEXT NULL,archive_color VARCHAR(7) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(parent_id),CONSTRAINT fk_cms_cat_parent FOREIGN KEY(parent_id) REFERENCES cms_categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");}catch(Throwable $e){}
        foreach([['post_type',"ENUM('post','page') NOT NULL DEFAULT 'post'"],['excerpt','TEXT NULL'],['visibility',"ENUM('public','private','password') NOT NULL DEFAULT 'public'"],['password_hash','VARCHAR(255) NULL'],['author_id','BIGINT UNSIGNED NULL'],['parent_id','BIGINT UNSIGNED NULL'],['template','VARCHAR(120) NULL'],['menu_order','INT NOT NULL DEFAULT 0'],['featured_image_url','TEXT NULL'],['transparent_header','TINYINT(1) NOT NULL DEFAULT 0'],['display_title','TINYINT(1) NOT NULL DEFAULT 1'],['layout',"VARCHAR(40) NOT NULL DEFAULT 'default'"],['content_style',"VARCHAR(40) NOT NULL DEFAULT 'default'"],['vertical_padding',"VARCHAR(40) NOT NULL DEFAULT 'default'"],['comments_enabled','TINYINT(1) NOT NULL DEFAULT 1'],['pings_enabled','TINYINT(1) NOT NULL DEFAULT 1'],['scheduled_at','DATETIME NULL'],['published_at','DATETIME NULL'],['deleted_at','DATETIME NULL']] as $c){try{$pdo->exec("ALTER TABLE cms_posts ADD COLUMN {$c[0]} {$c[1]}");}catch(Throwable $e){}}
        try{$pdo->exec("ALTER TABLE cms_posts MODIFY status ENUM('draft','published','trash','private','pending') NOT NULL DEFAULT 'draft'");}catch(Throwable $e){}
        try{$pdo->exec("ALTER TABLE cms_posts ADD INDEX(post_type)");}catch(Throwable $e){}
        try{$pdo->exec("UPDATE cms_posts SET author_id=user_id WHERE author_id IS NULL AND user_id IS NOT NULL");}catch(Throwable $e){}
        foreach([['description','TEXT NULL'],['parent_id','BIGINT UNSIGNED NULL'],['archive_color','VARCHAR(7) NULL'],['updated_at','DATETIME NULL']] as $c){try{$pdo->exec("ALTER TABLE cms_categories ADD COLUMN {$c[0]} {$c[1]}");}catch(Throwable $e){}}
    } catch(Throwable $e) {}
}
function cms_slug(string $value): string { $value=trim($value); $value=preg_replace('/[^a-z0-9]+/i','-',$value)??''; $value=trim($value,'-'); return strtolower($value?:'untitled'); }
function cms_unique_slug(string $slug,string $type,?int $id=null): string { $base=cms_slug($slug); $out=$base; $n=2; while(true){$q='SELECT id FROM cms_posts WHERE post_type=? AND slug=?'.($id?' AND id<>?':'').' LIMIT 1';$s=db()->prepare($q);$args=$id?[$type,$out,$id]:[$type,$out];$s->execute($args);if(!$s->fetchColumn())return $out;$out=$base.'-'.$n++;} }
function cms_terms(int $postId,string $kind): array { $table=$kind==='tag'?'cms_tags':'cms_categories';$join=$kind==='tag'?'cms_post_tags':'cms_post_categories';$col=$kind==='tag'?'tag_id':'category_id';$s=db()->prepare("SELECT t.* FROM {$table} t INNER JOIN {$join} j ON j.{$col}=t.id WHERE j.post_id=? ORDER BY t.name");$s->execute([$postId]);return $s->fetchAll(); }
function cms_revision(int $postId,array $row):void { $n=(int)db()->query('SELECT COALESCE(MAX(revision_no),0)+1 FROM cms_revisions WHERE post_id='.(int)$postId)->fetchColumn();$s=db()->prepare('INSERT INTO cms_revisions(post_id,revision_no,title,slug,content,meta_json,author_id,created_at) VALUES(?,?,?,?,?,?,?,NOW())');$meta=json_encode($row,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$s->execute([$postId,$n,$row['title'],$row['slug'],$row['content'],$meta,(int)(current_user()['id']??0)]);}
function cms_save_terms(int $postId,array $catIds,array $tagIds):void { $pdo=db();$pdo->prepare('DELETE FROM cms_post_categories WHERE post_id=?')->execute([$postId]);$pdo->prepare('DELETE FROM cms_post_tags WHERE post_id=?')->execute([$postId]);$s=$pdo->prepare('INSERT IGNORE INTO cms_post_categories(post_id,category_id) VALUES(?,?)');foreach($catIds as $id)if((int)$id>0)$s->execute([$postId,(int)$id]);$s=$pdo->prepare('INSERT IGNORE INTO cms_post_tags(post_id,tag_id) VALUES(?,?)');foreach($tagIds as $id)if((int)$id>0)$s->execute([$postId,(int)$id]);}
function cms_status_counts(string $type):array {$out=array_fill_keys(['all','published','draft','trash','pending'],0);$s=db()->prepare("SELECT status,COUNT(*) c FROM cms_posts WHERE post_type=? GROUP BY status");$s->execute([$type]);foreach($s as $r){$k=$r['status']==='private'?'published':$r['status'];if(isset($out[$k]))$out[$k]+=(int)$r['c'];}$out['all']=array_sum($out)-$out['trash'];return $out;}
function cms_comment_count(int $postId):int {$s=db()->prepare("SELECT COUNT(*) FROM cms_comments WHERE post_id=? AND status='approved'");$s->execute([$postId]);return (int)$s->fetchColumn();}
function cms_revision_rows(int $postId): array { $s=db()->prepare('SELECT r.*,u.full_name author_name FROM cms_revisions r LEFT JOIN users u ON u.id=r.author_id WHERE r.post_id=? ORDER BY r.revision_no DESC');$s->execute([$postId]);return $s->fetchAll(); }
function cms_revision_diff(string $old,string $new): array { $a=preg_split('/\R/',$old);$b=preg_split('/\R/',$new);$m=count($a);$n=count($b);$dp=array_fill(0,$m+1,array_fill(0,$n+1,0));for($i=$m-1;$i>=0;$i--)for($j=$n-1;$j>=0;$j--)$dp[$i][$j]=($a[$i]===$b[$j])?1+$dp[$i+1][$j+1]:max($dp[$i+1][$j],$dp[$i][$j+1]);$out=[];$i=0;$j=0;while($i<$m||$j<$n){if($i<$m&&$j<$n&&$a[$i]===$b[$j]){$out[]=['same',$a[$i]];$i++;$j++;continue;}if($j<$n&&($i===$m||$dp[$i][$j+1]>=$dp[$i+1][$j])){$out[]=['add',$b[$j++]];}else{$out[]=['remove',$a[$i++]];}}return $out;}
function cms_get_meta(int $postId,string $key,string $default=''): string { $s=db()->prepare('SELECT meta_value FROM cms_post_meta WHERE post_id=? AND meta_key=?');$s->execute([$postId,$key]);$v=$s->fetchColumn();return $v===false?$default:(string)$v; }
function cms_set_meta(int $postId,string $key,string $value): void { db()->prepare('INSERT INTO cms_post_meta(post_id,meta_key,meta_value,updated_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE meta_value=VALUES(meta_value),updated_at=NOW()')->execute([$postId,$key,$value]); }

function cms_restore_revision(int $postId,int $revisionId): bool {
    $st=db()->prepare('SELECT * FROM cms_revisions WHERE id=? AND post_id=? LIMIT 1'); $st->execute([$revisionId,$postId]); $rev=$st->fetch();
    if(!$rev) return false;
    $st=db()->prepare('SELECT * FROM cms_posts WHERE id=? LIMIT 1'); $st->execute([$postId]); $cur=$st->fetch();
    if(!$cur) return false;
    cms_revision($postId,$cur);
    $meta=json_decode((string)$rev['meta_json'],true) ?: [];
    $set=['title'=>$rev['title'],'slug'=>$rev['slug'],'content'=>$rev['content']];
    foreach(['excerpt','visibility','password_hash','author_id','parent_id','template','menu_order','featured_image_url','transparent_header','display_title','layout','content_style','vertical_padding','comments_enabled','pings_enabled'] as $k){if(array_key_exists($k,$meta))$set[$k]=$meta[$k];}
    $parts=[];$vals=[]; foreach($set as $k=>$v){$parts[]=$k.'=?';$vals[]=$v;} $parts[]='updated_at=NOW()'; $vals[]=$postId;
    db()->prepare('UPDATE cms_posts SET '.implode(',',$parts).' WHERE id=?')->execute($vals);
    return true;
}
function cms_publish_scheduled(): int {
    try { return (int)db()->exec("UPDATE cms_posts SET status='published',published_at=COALESCE(published_at,scheduled_at,NOW()),scheduled_at=NULL,updated_at=NOW() WHERE status='draft' AND scheduled_at IS NOT NULL AND scheduled_at<=NOW()"); } catch(Throwable $e) { return 0; }
}

function cms_pref_get(int $userId, string $key, string $default=''): string {
    if($userId<=0 || $key==='') return $default;
    try{$q=db()->prepare('SELECT pref_value FROM cms_user_preferences WHERE user_id=? AND pref_key=? LIMIT 1');$q->execute([$userId,$key]);$v=$q->fetchColumn();return $v===false?$default:(string)$v;}catch(Throwable $e){return $default;}
}
function cms_pref_set(int $userId, string $key, string $value): void {
    if($userId<=0 || $key==='') return;
    $s=db()->prepare('INSERT INTO cms_user_preferences(user_id,pref_key,pref_value,updated_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE pref_value=VALUES(pref_value),updated_at=NOW()');
    $s->execute([$userId,$key,$value]);
}
function cms_comment_children(array $comments): array {
    $tree=[]; foreach($comments as $c){$p=(int)($c['parent_id']??0);$tree[$p][]=$c;} return $tree;
}
